package fr.cercle.tourderole;
import java.util.*;import java.math.*;import java.text.Normalizer;import java.time.*;
public final class Core {
public static String norm(String s){return Normalizer.normalize(s==null?"":s,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).trim();}
public static boolean matches(String text,String query){String h=norm(text);for(String q:norm(query).split("[,;\\s]+"))if(!q.isEmpty()&&!h.contains(q))return false;return true;}
public static BigDecimal amount(String s){if(s==null||s.trim().isEmpty())return BigDecimal.ZERO;String clean=s.trim().replace(" ","");if(!clean.matches("[0-9]{1,12}([.,][0-9]{1,4})?"))throw new NumberFormatException("Nombre positif attendu, maximum12chiffres et4décimales");return new BigDecimal(clean.replace(',','.'));}
public static String money(BigDecimal n){return n.setScale(2,RoundingMode.HALF_UP).toPlainString()+" €";}
public static boolean date(String s){if(s==null||s.isEmpty())return true;try{LocalDate.parse(s);return true;}catch(Exception e){return false;}}
public static String today(){return LocalDate.now().toString();}public static String nextDate(String s,int days){return LocalDate.parse(s).plusDays(days).toString();}
public static int intValue(String s,int fallback){try{return Integer.parseInt(s.trim());}catch(Exception e){return fallback;}}
public static String nextPerson(String people,String current){List<String> a=new ArrayList<>();for(String n:people.split(","))if(!n.trim().isEmpty())a.add(n.trim());if(a.isEmpty())return "";return a.get((a.indexOf(current)+1)%a.size());}
public static long[] durations(String text){String[] parts=text.split(",");if(parts.length<1||parts.length>30)throw new IllegalArgumentException("1 à 30 étapes maximum");long[] out=new long[parts.length];for(int i=0;i<parts.length;i++){String[] t=parts[i].trim().split(":");long seconds;if(t.length==2){long m=Long.parseLong(t[0]),s=Long.parseLong(t[1]);if(m<0||s<0||s>=60)throw new IllegalArgumentException("Utilise MM:SS");seconds=Math.addExact(Math.multiplyExact(m,60),s);}else if(t.length==1)seconds=Long.parseLong(t[0])*60;else throw new IllegalArgumentException("Utilise MM:SS");if(seconds<=0||seconds>86400)throw new IllegalArgumentException("Étape : 1 seconde à 24 heures");out[i]=seconds*1000;}return out;}
public static String timer(long ms){long s=Math.max(0,ms/1000);return String.format(Locale.ROOT,"%02d:%02d",s/60,s%60);}
public static List<Integer> pages(String spec,int total){LinkedHashSet<Integer> out=new LinkedHashSet<>();if(total<1||total>1000)throw new IllegalArgumentException("PDF : 1 à 1000 pages");for(String p:spec.split(",")){String[] r=p.trim().split("-");int a=Integer.parseInt(r[0].trim()),b=r.length==1?a:Integer.parseInt(r[1].trim());if(r.length>2||a<1||b<a||b>total)throw new IllegalArgumentException("Pages hors limites");for(int i=a;i<=b;i++)out.add(i-1);}if(out.isEmpty())throw new IllegalArgumentException("Choisis des pages");return new ArrayList<>(out);}
public static String ingredient(String s){String n=norm(s).replaceAll("^[\\d\\s.,/]+","").replaceAll("^(kg|g|mg|ml|cl|l|cuilleres?)\\s+","").replaceAll("^(de |d'|du |des )","").trim();return n.replaceAll("s$","");}
public static boolean hasIngredient(String item,List<String> pantry){String n=ingredient(item);for(String p:pantry){String v=ingredient(p);if(!v.isEmpty()&&n.equals(v))return true;}return false;}
public static int weighted(List<Integer> weights,Random rng){long total=0;for(int w:weights){if(w<1||w>1000)throw new IllegalArgumentException("Poids de 1 à 1000");total+=w;}if(total==0)return -1;long pick=(long)(rng.nextDouble()*total);for(int i=0;i<weights.size();i++){pick-=weights.get(i);if(pick<0)return i;}return weights.size()-1;}
public static long review(long now,int grade,int previousDays){if(grade==0)return now+600000;return now+86400000L*(grade==1?1:Math.min(365,Math.max(2,previousDays*2)));}
public static int natural(String a,String b){String[] x=a.toLowerCase(Locale.ROOT).split("(?<=\\D)(?=\\d)|(?<=\\d)(?=\\D)"),y=b.toLowerCase(Locale.ROOT).split("(?<=\\D)(?=\\d)|(?<=\\d)(?=\\D)");for(int i=0;i<Math.min(x.length,y.length);i++){int c;if(x[i].matches("\\d+")&&y[i].matches("\\d+"))c=new BigInteger(x[i]).compareTo(new BigInteger(y[i]));else c=x[i].compareTo(y[i]);if(c!=0)return c;}return Integer.compare(x.length,y.length);}
public static String safeName(String name){return name.replaceAll("[^\\p{L}\\p{N}._ -]","_").replace("..","_");}
}